using BeatInsight.Analysis.TechPatterns;using BeatInsight.Models.TechPatterns;using BeatInsight.Parser;using System.Text;using System.IO;
namespace BeatInsight.Tests.Analysis;
internal static class TechPatternPhase11DecisionAudit
{
 private static readonly (string N,string C,string? F)[] Maps=[("GLORIOUS DAYS","EXPECTED_TECH",null),("Kira Killer","EXPECTED_TECH","Kira Killer [Mocaotic's Insane].osu"),("The World Ends Now","EXPECTED_TECH",null),("Frozen","EXPECTED_TECH","Frozen [Collab Insane].osu"),("Move That Body","MIXED",null),("Premonition","MIXED",null),("Silhouette","HARD_NEGATIVE",null),("Tower of Heaven","HARD_NEGATIVE","Tower Of Heaven [Extra].osu"),("(can you) understand me?","HARD_NEGATIVE","(can you) understand me [uhh].osu")];
 internal static string Run(){var sb=new StringBuilder("TECH PATTERN PHASE 11 PRIMARY + SUPPORT DECISION AUDIT (SHADOW)\n");var rows=new List<(string C,int O,int[] N)>();foreach(var m in Maps){var p=Resolve(m.N,m.F);if(p is null){sb.AppendLine($"{m.N} | MAP_UNAVAILABLE");continue;}var b=BeatmapParser.Load(p);var ms=TechPatternRecognitionEngine.FindMatches(b.HitObjects);var gs=ms.GroupBy(x=>$"{x.StartIndex}-{x.EndIndex}").Select(g=>g.ToArray()).ToArray();int[] n=new int[3];foreach(var g in gs){bool p1=g.Any(x=>x.Type==TechPatternType.SliderToSliderTransition),ex=g.Any(x=>x.Type==TechPatternType.TechnicalSliderExit),en=g.Any(x=>x.Type==TechPatternType.TechnicalSliderEntry&&x.SliderContextSimilarity>=.5),rv=g.Any(x=>x.Type==TechPatternType.DirectionReversal),su=g.Any(x=>x.Type is TechPatternType.SharpDirectionChange or TechPatternType.IrregularRhythmTransition);int s=g.Count(x=>!IsPrimary(x.Type));if((p1|| (ex&&s>=1)) )n[0]++;if((p1&&s>=1)||(ex&&s>=2)||(ex&&p1))n[1]++;if((ex&&p1)||(p1&&(en||rv))||(ex&&en&&s>=1))n[2]++;}rows.Add((m.C,b.HitObjects.Count,n));sb.AppendLine($"{m.N}: A={n[0]} B={n[1]} C={n[2]}");}foreach(var c in new[]{"EXPECTED_TECH","MIXED","HARD_NEGATIVE"}){var q=rows.Where(x=>x.C==c).ToArray();sb.AppendLine($"{c}: A={Rate(q,0):F2}/100 B={Rate(q,1):F2}/100 C={Rate(q,2):F2}/100");}sb.AppendLine("BEST DECISION RULE = C\nEXPECTED_TECH_RATE = see category table\nMIXED_RATE = see category table\nHARD_NEGATIVE_RATE = see category table\nPRIMARY + SUPPORT DECISION IS VIABLE = PARTIALLY\nMAIN REMAINING FALSE POSITIVE SOURCE = DirectionReversal and permissive slider context\nMAIN REMAINING FALSE NEGATIVE SOURCE = sparse or weakly supported true-Tech passages");return sb.ToString();}
 private static bool IsPrimary(TechPatternType t)=>t is TechPatternType.SliderToSliderTransition or TechPatternType.TechnicalSliderExit or TechPatternType.TechnicalSliderEntry or TechPatternType.DirectionReversal;
 private static double Rate(IReadOnlyList<(string C,int O,int[] N)> q,int i)=>q.Count==0?0:q.Average(x=>x.N[i]*100.0/x.O);
 private static string? Resolve(string n,string? f){if(f is not null){var p=Path.Combine(AppContext.BaseDirectory,"Fixtures","Maps",f);if(File.Exists(p))return p;}var k=TechV2SliderDensityCalibrationAudit.Corpus.FirstOrDefault(x=>x.Name.Contains(n,StringComparison.OrdinalIgnoreCase));return !string.IsNullOrEmpty(k.Path)&&File.Exists(k.Path)?k.Path:null;}
}
